"""High-performance LRU Cache implementation with doubly linked list."""
from typing import Generic, TypeVar, Optional, Dict

K = TypeVar('K')
V = TypeVar('V')

class Node(Generic[K, V]):
    def __init__(self, key: K, val: V):
        self.key: K = key
        self.val: V = val
        self.prev: Optional['Node[K, V]'] = None
        self.next: Optional['Node[K, V]'] = None

class LRUCache(Generic[K, V]):
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity: int = capacity
        self.cache: Dict[K, Node[K, V]] = {}
        self.head: Node[K, V] = Node(None, None)  # Dummy head
        self.tail: Node[K, V] = Node(None, None)  # Dummy tail
        self.head.next = self.tail
        self.tail.prev = self.head

    def _remove(self, node: Node[K, V]) -> None:
        p = node.prev
        n = node.next
        if p and n:
            p.next = n
            n.prev = p

    def _add_to_front(self, node: Node[K, V]) -> None:
        node.prev = self.head
        node.next = self.head.next
        if self.head.next:
            self.head.next.prev = node
        self.head.next = node

    def get(self, key: K) -> Optional[V]:
        if key not in self.cache:
            return None
        node = self.cache[key]
        self._remove(node)
        self._add_to_front(node)
        return node.val

    def put(self, key: K, val: V) -> None:
        if key in self.cache:
            node = self.cache[key]
            node.val = val
            self._remove(node)
            self._add_to_front(node)
        else:
            if len(self.cache) >= self.capacity:
                lru = self.tail.prev
                if lru and lru.key is not None:
                    self._remove(lru)
                    del self.cache[lru.key]
            new_node = Node(key, val)
            self.cache[key] = new_node
            self._add_to_front(new_node)

/**
 * Production-ready Event Emitter with wildcard listener support.
 */
class EventEmitter {
  constructor() {
    this.events = new Map();
  }

  on(event, listener) {
    if (typeof listener !== 'function') {
      throw new TypeError('Listener must be a function');
    }
    if (!this.events.has(event)) {
      this.events.set(event, new Set());
    }
    this.events.get(event).add(listener);
    return () => this.off(event, listener);
  }

  off(event, listener) {
    if (!this.events.has(event)) return;
    const listeners = this.events.get(event);
    listeners.delete(listener);
    if (listeners.size === 0) {
      this.events.delete(event);
    }
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return false;
    for (const listener of this.events.get(event)) {
      try {
        listener(...args);
      } catch (err) {
        console.error(`Error in event listener for ${event}:`, err);
      }
    }
    return true;
  }
}
module.exports = EventEmitter;

/**
 * Type-Safe Finite State Machine (FSM)
 */
export type State = 'IDLE' | 'LOADING' | 'SUCCESS' | 'ERROR';
export type Action = 
  | { type: 'FETCH' }
  | { type: 'RESOLVE'; payload: unknown }
  | { type: 'REJECT'; error: Error }
  | { type: 'RESET' };

export interface Transition<S extends State, A extends Action['type']> {
  from: S;
  action: A;
  to: State;
}

export class StateMachine {
  private currentState: State = 'IDLE';

  public getState(): State {
    return this.currentState;
  }

  public dispatch(action: Action): State {
    switch (this.currentState) {
      case 'IDLE':
        if (action.type === 'FETCH') this.currentState = 'LOADING';
        break;
      case 'LOADING':
        if (action.type === 'RESOLVE') this.currentState = 'SUCCESS';
        else if (action.type === 'REJECT') this.currentState = 'ERROR';
        break;
      case 'SUCCESS':
      case 'ERROR':
        if (action.type === 'RESET') this.currentState = 'IDLE';
        break;
    }
    return this.currentState;
  }
}

package circuitbreaker

import (
	"errors"
	"sync"
	"time"
)

var (
	ErrCircuitOpen = errors.New("circuit breaker is open")
)

type State int

const (
	StateClosed State = iota
	StateHalfOpen
	StateOpen
)

type CircuitBreaker struct {
	mu           sync.Mutex
	state        State
	failureCount int
	threshold    int
	timeout      time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:     StateClosed,
		threshold: threshold,
		timeout:   timeout,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	cb.mu.Lock()
	if cb.state == StateOpen {
		if time.Since(cb.lastFailure) > cb.timeout {
			cb.state = StateHalfOpen
		} else {
			cb.mu.Unlock()
			return ErrCircuitOpen
		}
	}
	cb.mu.Unlock()

	err := fn()

	cb.mu.Lock()
	defer cb.mu.Unlock()

	if err != nil {
		cb.failureCount++
		cb.lastFailure = time.Now()
		if cb.failureCount >= cb.threshold {
			cb.state = StateOpen
		}
		return err
	}

	if cb.state == StateHalfOpen {
		cb.state = StateClosed
		cb.failureCount = 0
	}
	return nil
}

